import Application, { Item } from "../models/Application";
import Offer from "../models/Offer";
import OfferService from "../services/OfferService";
export default class OfferEditPageController {
    constructor(preview, form, createButton, updateButton, deleteButton) {
        this.preview = preview;
        this.form = form;
        this.createButton = createButton;
        this.updateButton = updateButton;
        this.deleteButton = deleteButton;
        this.application = Application.getInstance();
        this.currentUser = Application.getInstance().get(Item.CurrentUser);
        this.offer = new Offer();
        this.initialize();
    }
    async initialize() {
        // URL parameters
        const urlParams = new URLSearchParams(window.location.search);
        const offerID = urlParams.get("id");
        if (!offerID) {
            console.log("Offer ID is missing in URL parameters.");
            return;
        }
        // Load offer data
        try {
            this.offer = await OfferService.getByID(offerID);
        }
        catch (error) {
            console.error("Failed to load offer:", error);
            return;
        }
        // Update form and preview
        this.form.update(this.offer);
        this.preview.update(this.offer);
        this.connectEvents();
    }
    connectEvents() {
        this.createButton.onclick = (event) => this.onCreateButton(event);
        this.updateButton.onclick = (event) => this.onUpdateButton(event);
        this.deleteButton.onclick = (event) => this.onDeleteButton(event);
        this.form.oninput = () => this.onChange();
    }
    async onCreateButton(event) {
        event.preventDefault();
        let newOffer;
        try {
            newOffer = await OfferService.create(this.offer, this.currentUser);
        }
        catch (error) {
            alert(error.message);
            return;
        }
        window.location.href = `/offer?id=${newOffer._id}`;
    }
    async onUpdateButton(event) {
        event.preventDefault();
        this.offer = this.form.getEntries();
        try {
            await OfferService.update(this.offer, this.currentUser);
        }
        catch (error) {
            alert(error.message);
            return;
        }
        window.location.href = `/offer?id=${this.offer._id}`;
    }
    async onDeleteButton(event) {
        event.preventDefault();
        try {
            await OfferService.delete(this.offer, this.currentUser);
        }
        catch (error) {
            alert(error.message);
            return;
        }
        window.location.href = `/user?id=${this.offer.sellerID}`;
    }
    onChange() {
        this.offer = this.form.getEntries();
        this.preview.update(this.offer);
    }
}
